constraints:
1 ≤ N ≤ 10^{5}

expected time complexity: O(|str|).
expected auxiliary space: O(|str|).

standard_solution_code:
class Solution:

	def convert(self, Str, n):
		row = 0
		direction = 1
		output = [''] * n
		for char in Str:
			output[row] = output[row] + char
			if row < n - 1 and direction == 1:
				row += 1
			elif row > 0 and direction == -1:
				row -= 1
			else:
				direction *= -1
				row += direction
		return ''.join(output)
